  growCrop: {
    c1: "Les tomates réussissent dans votre zone avec un peu d'organisation. Semez-les à l'intérieur six à huit semaines avant les dernières gelées, endurcissez-les et plantez-les quand les nuits restent au-dessus de 50°F.",
    c2: "Les poivrons ont besoin de chaleur pour démarrer en zone tempérée. Semez-les tôt à l'intérieur, attendez que le sol se réchauffe pour repiquer et comptez sur la grosse récolte en fin d'été.",
    c3: "La laitue est une culture de printemps et d'automne chez vous — elle monte en graine avec la chaleur. Semez peu et souvent, et offrez-lui de l'ombre l'après-midi pour prolonger la saison.",
    c4: "L'épinard convient à votre zone pendant la moitié fraîche de l'année. Semez au début du printemps et de nouveau en fin d'été pour une coupe d'automne ; semé en plein été, il monte en graine.",
    c5: "Le chou kale est l'une des cultures les plus faciles en zone tempérée et tient presque tout l'hiver. Semez en plein été pour récolter en automne et en hiver — les feuilles s'adoucissent après les premières gelées.",
    c6: "Les choux réussissent mieux avant et après l'été chez vous. Semez à l'intérieur et repiquez pour une récolte de printemps, ou semez en plein été pour une meilleure récolte d'automne, et protégez-les de la piéride avec un filet.",
    c7: "Les carottes poussent bien chez vous en semis de début de printemps puis en plein été pour des racines d'automne. Donnez-leur un sol profond sans cailloux et éclaircissez, sinon elles seront fourchues et chétives.",
    c8: "L'ail est une culture classique de zone tempérée et a besoin de votre hiver. Plantez les caïeux à l'automne pour qu'ils reçoivent le froid nécessaire à la formation d'une tête, et récoltez quand les feuilles basses brunissent en été.",
    c9: "Les pois adorent le début frais de la saison. Semez dès que le sol est travaillable, donnez-leur un support et cueillez souvent — ils s'arrêtent quand la chaleur arrive.",
    c10: "Les haricots sont une culture d'été fiable chez vous mais détestent le sol froid. Semez après les dernières gelées, refaites un semis quelques semaines plus tard et cueillez souvent pour qu'ils continuent.",
    c11: "Cette plante se plaît dans un été tempéré une fois le froid passé. Plantez après les dernières gelées dans un sol riche, arrosez au pied plutôt que sur les feuilles, et attendez-vous à plus que prévu.",
    c12: "Les patates douces ne sont pas des pommes de terre et demandent une saison chaude, que votre zone offre de justesse. Plantez les boutures racinées bien après les gelées dans un sol bien chaud et récoltez avant la première gelée d'automne.",
    c13: "Les pommes de terre aiment le long printemps frais de votre zone. Plantez les plants quelques semaines avant les dernières gelées, buttez-les à la levée et récoltez les tardives quand le feuillage sèche.",
    c14: "Les fraisiers sont vivaces chez vous et produisent davantage la deuxième année. Plantez au printemps ou à l'automne, paillez sous les fruits pour les garder propres et protégez les cœurs pendant les semaines les plus froides.",
    c15: "Le basilic est la plante fragile du jardin tempéré. Gardez-le à l'intérieur jusqu'à ce que les nuits dépassent sûrement 50°F, offrez-lui l'endroit le plus ensoleillé et pincez les extrémités pour retarder la floraison.",
    c16: "Votre zone lui apporte le froid hivernal nécessaire pour bien fructifier, ce que les zones chaudes ne peuvent pas. Plantez un arbre à racines nues en dormance, taillez pour aérer le centre et éclaircissez une forte charge pour soulager les branches.",
    c17: "Les tomates prospèrent en zone chaude mais demandent un arrosage profond régulier et du paillis pour passer l'été. Choisissez des variétés tolérantes à la chaleur comme Solar Fire ou Heatmaster.",
    c18: "Les poivrons sont parmi les meilleurs légumes des zones chaudes — ils adorent la chaleur et produisent en abondance. Arrosez régulièrement et profitez d'une longue saison productive.",
    c19: "Le basilic prospère au chaud et au soleil, idéal pour votre zone. Plantez après les dernières gelées en plein soleil et pincez régulièrement les fleurs pour garder des feuilles parfumées.",
    c20: "La pastèque est un excellent choix en zone chaude — la chaleur accélère la croissance et la douceur. Donnez de l'espace, arrosez profondément chaque semaine et profitez d'une belle récolte.",
    c21: "Le gombo est l'un des meilleurs légumes des climats chauds et pousse presque sans soin. Plantez en plein soleil et récoltez tous les 2 jours en pleine saison.",
    c22: "L'aubergine adore la chaleur et réussit très bien en zone chaude. Gardez le sol toujours humide et profitez d'une longue saison productive.",
    c23: "Les patates douces sont faites pour les zones chaudes — elles adorent la chaleur et produisent beaucoup sur les longues saisons. Plantez les boutures après les gelées et laissez de la place aux tiges.",
    c24: "Le chou kale est l'un des meilleurs légumes des zones froides — il gagne en saveur après le gel. Plantez en fin d'été pour une récolte d'automne et de début d'hiver de plus en plus douce.",
    c25: "L'épinard prospère en zone froide et se plante parmi les premiers au printemps. Il supporte les gelées légères et donne des feuilles tendres par temps frais.",
    c26: "Les pois sont parfaits en zone froide — ils aiment la fraîcheur et se sèment dès que le sol est travaillable au printemps. Attendez-vous à une bonne récolte avant la chaleur.",
    c27: "Les pommes de terre conviennent bien aux zones froides aux longues saisons fraîches. Plantez des plants certifiés au début du printemps pour une récolte généreuse en fin d'été.",
    c28: "Les carottes prospèrent en climat frais et deviennent très sucrées après de légères gelées. Semez dans un sol profond, meuble et sans cailloux pour des racines droites et bien formées.",
    c29: "Le brocoli est idéal en zone froide — il aime la fraîcheur et produit mieux au printemps ou à l'automne. Semez tôt à l'intérieur et repiquez quand il fait plus frais pour une récolte de premier choix.",
  },
