    rootKnotNematode_sign: "Plantes rabougries et flétries avec des galles noueuses sur les racines.",
    rootKnotNematode_damage: "Les racines galleuses ne peuvent plus absorber l'eau et les nutriments, si bien que les plantes flétrissent et produisent peu.",
    spittlebug_sign: "Amas d'écume « de crachat » sur les tiges, avec une nymphe cachée à l'intérieur.",
    spittlebug_damage: "Une forte infestation peut freiner la croissance des nouvelles pousses, mais la plupart des plantes s'en accommodent.",
    spottedWingDrosophila_sign: "Baies mûres molles, affaissées, qui s'effondrent vite, avec de minuscules larves à l'intérieur.",
