    fusariumRot_spreads: "Stockage chaud et humide et blessures de récolte.",
    panamaDisease_sign: "Les vieilles feuilles jaunissent, flétrissent et s'affaissent en jupe autour du pseudo-tronc ; en fendant le tronc, on voit des stries brun-rouge foncé.",
    panamaDisease_treat: "Pas de remède : arrachez et détruisez les touffes atteintes et ne replantez pas de bananiers sensibles dans ce sol.",
