    blackSigatoka_prevent: "Espacez les plants, taillez les vieilles feuilles pour aérer, assurez un bon drainage et retirez rapidement les feuilles infectées.",
    cornSmut_name: "Charbon du maïs",
    cornSmut_damage: "Détruit les grains qu'il infecte et peut déformer les tiges ; les spores persistent des années dans le sol.",
    cornSmut_spreads: "Temps chaud, blessures sur les plantes et spores présentes dans le sol.",
