    sootyMold_spreads: "Miellat de pucerons, cochenilles, aleurodes et cochenilles farineuses.",
    dampingOff_sign: "Les graines ne lèvent pas, ou les semis sortent puis s'affaissent brusquement, avec une tache sombre, fine, étranglée et gorgée d'eau à la base de la tige.",
    dampingOff_treat: "Un semis effondré ne peut pas être sauvé : retirez-le, laissez sécher le terreau, augmentez l'aération et la lumière, puis ressemez dans du terreau stérile neuf.",
    popcornDisease_description: "Maladie fongique des mûriers qui gonfle chaque petit fruit, si bien que la mûre ressemble à du pop-corn soufflé.",
    popcornDisease_prevent: "Ratissez et détruisez les fruits infectés tombés et les fruits momifiés, et taillez pour aérer.",
    powderyMildew_description: "Une maladie fongique très courante qui recouvre feuilles, tiges et bourgeons d'un feutrage poudreux blanc à gris. Elle prospère avec des journées chaudes, des nuits fraîches et des plantations denses et ombragées.",
    powderyMildew_prevent: "Espacez et taillez pour aérer, plantez en plein soleil, évitez d'arroser sur le feuillage, choisissez des variétés résistantes et allez-y doucement avec l'azote.",
    downyMildew_name: "Mildiou",
