    downyMildew_spreads: "Temps frais, pluvieux et humide, avec un feuillage mouillé longtemps.",
    earlyBlight_sign: "Taches brunes à anneaux concentriques, en « cible », souvent entourées d'un halo jaune. Elles débutent en bas et montent.",
